INSERT INTO "ObservatoryClaim"
("id","caseId","claimType","statement","constructId","epistemicStatus","verificationStatus","confidence","permissibleLanguage","contradictionNote","publicStatus","createdAt","updatedAt")
VALUES
('obs_claim_ms_c01',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='mustafa-suleyman'),'organization_formation','Microsoft announced Microsoft AI on 19 March 2024 as a new organization.','institution_building','observed','unreviewed',NULL,'Microsoft formed a new organization called Microsoft AI in March 2024.','Formation does not establish Suleyman ownership or sole invention.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_ms_c02',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='mustafa-suleyman'),'executive_appointment','Suleyman became EVP and CEO of Microsoft AI, joined the senior leadership team and reported to Satya Nadella.','formal_authority','observed','unreviewed',NULL,'Microsoft appointed Suleyman EVP and CEO of Microsoft AI, reporting to Satya Nadella.','The title did not grant authority over all Microsoft AI activity.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_ms_c03',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='mustafa-suleyman'),'scientific_leadership','Karén Simonyan joined as chief scientist and reported to Suleyman.','distributed_leadership','observed','unreviewed',NULL,'Karén Simonyan joined Microsoft AI as chief scientist.','Do not attribute scientific leadership solely to Suleyman.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_ms_c04',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='mustafa-suleyman'),'transferred_teams','Existing Copilot, Bing, Edge and GenAI teams moved into Suleyman''s reporting line in 2024.','resource_assembly','observed','unreviewed',NULL,'Microsoft AI combined transferred Microsoft teams with incoming personnel.','Suleyman and Inflection did not originate those existing products.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_ms_c05',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='mustafa-suleyman'),'retained_governance','Kevin Scott retained company-wide AI strategy and architecture authority while Rajesh Jha retained Microsoft 365 Copilot responsibility.','governance_accountability','observed','unreviewed',NULL,'Microsoft preserved material AI authority outside Microsoft AI.','Microsoft AI was not Microsoft''s sole AI authority.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_ms_c06',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='mustafa-suleyman'),'openai_dependency','Microsoft stated that its OpenAI partnership and supporting infrastructure work would continue.','institutional_dependency','observed','unreviewed',NULL,'Microsoft AI was formed within a wider Microsoft–OpenAI architecture.','Do not describe Microsoft AI as technologically independent in 2024.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_ms_c07',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='mustafa-suleyman'),'inflection_arrangements','Microsoft hired Inflection leaders and employees and entered associated licensing arrangements with Inflection.','institutional_portability','observed','unreviewed',NULL,'Microsoft AI''s formation included personnel transfer and licensed Inflection technology.','Microsoft did not publicly describe the arrangement as an outright Inflection acquisition.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_ms_c08',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='mustafa-suleyman'),'regulatory_review','The UK CMA found a relevant merger situation and cleared the arrangements after finding no realistic prospect of substantial lessening of competition.','governance_accountability','observed','unreviewed',NULL,'UK regulators reviewed and cleared the Microsoft–Inflection arrangements.','Clearance does not erase structural significance or resolve every jurisdiction.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_ms_c09',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='mustafa-suleyman'),'london_hub','Microsoft AI opened a London hub led by Jordan Hoffmann for model and infrastructure work.','resource_assembly','observed','unreviewed',NULL,'Microsoft AI expanded its capacity through a London hub.','Hub outputs are institutional and collaborative.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_ms_c10',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='mustafa-suleyman'),'model_outputs','Microsoft AI announced internally developed model families and product deployments in 2025 and 2026.','institutional_outputs','observed','unreviewed',NULL,'Teams within Microsoft AI released Microsoft-developed model families.','Do not say Suleyman personally invented or trained the models.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_ms_c11',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='mustafa-suleyman'),'remit_change','Microsoft changed Copilot and model leadership in March 2026, shifting Suleyman''s principal focus toward frontier models and superintelligence.','role_evolution','observed','unreviewed',NULL,'Suleyman retained the CEO title but shifted his principal focus toward frontier models and superintelligence.','His March 2024 product remit did not remain unchanged.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_ms_c12',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='mustafa-suleyman'),'copilot_governance','Jacob Andreou became EVP of Copilot reporting to Nadella while a cross-functional leadership team connected product, platform, applications and models.','distributed_leadership','observed','unreviewed',NULL,'Current Copilot authority is distributed across named leaders.','Suleyman does not have exclusive day-to-day control of unified Copilot.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_ms_c13',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='mustafa-suleyman'),'career_chronology','Suleyman previously co-founded DeepMind, led applied AI, moved to Google product and policy, joined Greylock and co-founded Inflection.','institutional_portability','observed','unreviewed',NULL,'His appointment followed roles across DeepMind, Google, Greylock and Inflection.','Prior institutional outputs are not solely his work or property.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_ms_c14',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='mustafa-suleyman'),'management_boundary','Public sources document management complaints at DeepMind and Suleyman''s later apology.','governance_accountability','observed','unreviewed',NULL,'A complete leadership record includes reported management complaints and Suleyman''s public apology.','Do not diagnose motive, personality or stable psychological disposition.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_ms_c15',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='mustafa-suleyman'),'data_governance_boundary','The Royal Free–DeepMind health-data project generated a privacy finding against the Trust.','governance_accountability','observed','unreviewed',NULL,'DeepMind Health''s institutional history includes a material data-governance controversy.','Do not attribute the legal finding personally to Suleyman.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_ms_c16',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='mustafa-suleyman'),'bounded_role_architecture','Microsoft created a role with substantial organizational authority and assembled resources around it while retaining distributed governance.','role_centered_architecture','interpretive','unreviewed',NULL,'Microsoft formed a role-centered organization around Suleyman, but authority and causation remained distributed.','Prohibit invented-empire and sole-causation language.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('obs_claim_ms_c17',(SELECT "id" FROM "ObservatoryCase" WHERE "slug"='mustafa-suleyman'),'psychology_boundary','No reviewed source measures Suleyman''s psychological constructs.','claim_restriction','observed','unreviewed',NULL,'The case measures roles, resources, relationships and outputs; it does not measure psychology.','Do not score ambition, empathy, ethics or leadership psychology from biography.','draft',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
